fn contains_consecutive_numbers(a: &[i32]) -> bool {
    // If the slice has fewer than 2 elements, there can't be an adjacent pair.
    if a.len() < 2 {
        return false;
    }

    // Check each adjacent pair.
    for i in 0..a.len() - 1 {
        if a[i] + 1 == a[i + 1] {
            return true;
        }
    }
    false
}

